mapper.select:
SELECT u.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, d.dept_name AS deptName FROM v_identity_user u JOIN v_identity_dept d ON d.dept_id = u.dept_id WHERE u.status = '0' AND u.del_flag = '0' AND d.status = '0' AND d.del_flag = '0' AND (d.dept_id = #{organizationId} OR FIND_IN_SET(#{organizationId}, d.ancestors)) AND NOT EXISTS (SELECT 1 FROM v_identity_dept ancestor WHERE FIND_IN_SET(ancestor.dept_id, d.ancestors) AND (ancestor.status <> '0' OR ancestor.del_flag <> '0')) AND EXISTS (SELECT 1 FROM v_identity_user_role ur JOIN v_identity_role r ON r.role_id = ur.role_id WHERE ur.user_id = u.user_id AND r.role_key = 'teacher' AND r.status = '0' AND r.del_flag = '0') AND u.user_id <> (SELECT owner_user_id FROM edu_course_space WHERE id = #{courseId}) AND u.user_id = #{userId}
AND (u.user_name LIKE CONCAT('%', #{keyword}, '%') OR u.nick_name LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY u.user_name, u.user_id

mapper.insert:
INSERT INTO edu_course_teacher(course_space_id, user_id, can_manage_students, can_export, added_by_user_id)
VALUES (#{courseId}, #{userId}, #{manageStudents}, #{export}, #{operatorId})
ON DUPLICATE KEY UPDATE can_manage_students = #{manageStudents}, can_export = #{export}

mapper.update:
UPDATE edu_course_teacher
SET ended_at = GREATEST(NOW(3), TIMESTAMPADD(MICROSECOND, 1000, joined_at)), ended_by_user_id = #{operatorId}
WHERE course_space_id = #{courseId} AND user_id = #{userId} AND ended_at IS NULL

mapper.select:
SELECT user_id FROM edu_class_student WHERE teaching_class_id = #{classId}
  AND joined_at <= NOW(3) AND (left_at IS NULL OR left_at > NOW(3))
  AND user_id IN #{id}
ORDER BY user_id

mapper.update:
UPDATE edu_class_student SET left_at = GREATEST(NOW(3), TIMESTAMPADD(MICROSECOND, 1000, joined_at)),
    left_by_user_id = #{operatorId}, leave_reason = #{reason}
WHERE teaching_class_id = #{classId} AND joined_at <= NOW(3) AND (left_at IS NULL OR left_at > NOW(3))
  AND user_id IN #{id}
